def copy_m2m_scope_to_fk(apps, schema_editor):
    """Preserve existing CalibrationLog scope M2M data into the new single FK
    (uses the first selected scope, matching the equipment-level model)."""
    CalibrationLog = apps.get_model('core', 'CalibrationLog')
    for log in CalibrationLog.objects.all():
        first = log.scope.first()
        if first:
            log.scope_new_id = first.id
            log.save(update_fields=['scope_new_id'])


